INSERT INTO fraud_rule (rule_id, rule_code, rule_name, description, threshold_count, window_minutes, threshold_amount, severity, is_active) VALUES
  (1, 'VELOCITY', 'Payment velocity', '5 or more successful payments from one VPA within 10 minutes', 5, 10, NULL, 'HIGH', TRUE),
  (2, 'HIGH_VALUE_NEW_PAYEE', 'High value to new payee', 'Rs. 50,000+ sent to a VPA the payer has never paid before', NULL, NULL, 50000, 'CRITICAL', TRUE),
  (3, 'NIGHT_HIGH_VALUE', 'Night-time high value', 'Rs. 20,000+ paid between 00:00 and 05:00', NULL, NULL, 20000, 'MEDIUM', TRUE),
  (4, 'NEW_DEVICE', 'New device high value', 'Rs. 10,000+ paid from a device first seen in the last 24 hours', NULL, NULL, 10000, 'HIGH', TRUE),
  (5, 'HIGH_RISK_MERCHANT', 'High-risk merchant category', 'Rs. 25,000+ paid to a merchant in a HIGH risk category', NULL, NULL, 25000, 'HIGH', TRUE),
  (6, 'ROUND_AMOUNT', 'Repeated round amounts', 'Several exact round-figure transfers in a day (rule disabled - under review)', 3, 1440, 10000, 'LOW', FALSE);
